import math


def to_polar(z):
    return (math.hypot(z.real, z.imag), math.atan2(z.imag, z.real))


def from_polar(r, theta):
    return complex(r * math.cos(theta), r * math.sin(theta))

import math


def ar2_cycle(phi1, phi2):
    disc = phi1 * phi1 + 4 * phi2
    if disc >= 0:
        return None
    re, im = phi1 / 2, math.sqrt(-disc) / 2
    theta = math.atan2(im, re)
    return (math.hypot(re, im), 2 * math.pi / theta)
